package ch.jalu.configme.configurationdata;

import org.junit.Test;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import static org.hamcrest.CoreMatchers.is;
import static org.junit.Assert.assertThat;

public class CommentsConfigurationTest {

    @Test
    public void commentsConfigurationDefaultConstructorTest() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();

        assertThat(commentsConfiguration.getAllComments().isEmpty(), is(true));
    }

    @Test
    public void commentsConfigurationWithParamConstructorTest() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("path1", Arrays.asList("comment1", "comment2"));
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration(comments);

        assertThat(commentsConfiguration.getAllComments(), is(comments));
    }

    @Test
    public void setCommentTest() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        String path = "example.path";
        String commentLine1 = "Example comment 1";
        String commentLine2 = "Example comment 2";

        commentsConfiguration.setComment(path, commentLine1, commentLine2);

        assertThat(commentsConfiguration.getAllComments().get(path), is(Arrays.asList(commentLine1, commentLine2)));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void getAllCommentsReturnsImmutableMapTest() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        String path = "example.path";
        String commentLine = "Example comment";

        commentsConfiguration.setComment(path, commentLine);
        commentsConfiguration.getAllComments().put("illegal.path", Arrays.asList("Illegal comment"));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void setCommentCreatesImmutableListTest() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        String path = "example.path";
        String commentLine = "Example comment";

        commentsConfiguration.setComment(path, commentLine);
        commentsConfiguration.getAllComments().get(path).add("Illegal comment");
    }
}
